class Solution { private int mapped(int value,int[] mapping){if(value==0)return mapping[0];int result=0,place=1;while(value>0){result+=mapping[value%10]*place;place*=10;value/=10;}return result;}public int[] sortJumbled(int[] mapping,int[] nums){Integer[] order=new Integer[nums.length];int[] values=new int[nums.length];for(int i=0;i<nums.length;i++){order[i]=i;values[i]=mapped(nums[i],mapping);}Arrays.sort(order,(a,b)->values[a]!=values[b]?Integer.compare(values[a],values[b]):Integer.compare(a,b));int[] answer=new int[nums.length];for(int i=0;i<nums.length;i++)answer[i]=nums[order[i]];return answer;} }
